CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','staff','guardian')), full_name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS staff (id BIGSERIAL PRIMARY KEY, full_name TEXT NOT NULL, role_title TEXT NOT NULL, years_experience INTEGER NOT NULL DEFAULT 0 CHECK(years_experience BETWEEN 0 AND 70), biography TEXT NOT NULL DEFAULT '', published BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS students (id BIGSERIAL PRIMARY KEY, student_number TEXT UNIQUE, full_name TEXT NOT NULL, class_name TEXT NOT NULL, academic_year INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS guardian_students (guardian_user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE, PRIMARY KEY(guardian_user_id,student_id));
CREATE TABLE IF NOT EXISTS enrollments (id BIGSERIAL PRIMARY KEY, guardian_name TEXT NOT NULL, guardian_email TEXT NOT NULL, guardian_phone TEXT NOT NULL, student_name TEXT NOT NULL, form_level TEXT NOT NULL, academic_year INTEGER NOT NULL, notes TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','reviewing','accepted','declined')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS milestones (id BIGSERIAL PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', academic_year INTEGER NOT NULL, student_name TEXT, consent_confirmed BOOLEAN NOT NULL DEFAULT false, published BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT student_public_consent CHECK(NOT (published AND student_name IS NOT NULL AND consent_confirmed = false)));
CREATE TABLE IF NOT EXISTS conversations (id BIGSERIAL PRIMARY KEY, guardian_user_id BIGINT NOT NULL REFERENCES users(id), staff_user_id BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(guardian_user_id,staff_user_id));
CREATE TABLE IF NOT EXISTS messages (id BIGSERIAL PRIMARY KEY, conversation_id BIGINT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender_user_id BIGINT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments (id BIGSERIAL PRIMARY KEY, enrollment_id BIGINT REFERENCES enrollments(id), amount_cents BIGINT NOT NULL CHECK(amount_cents>=0), currency TEXT NOT NULL DEFAULT 'USD', provider TEXT, provider_reference TEXT UNIQUE, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','failed','refunded')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, actor_user_id BIGINT REFERENCES users(id), action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_messages_conversation ON messages(conversation_id,id);
CREATE INDEX IF NOT EXISTS idx_enrollments_status ON enrollments(status,created_at);
ALTER TABLE staff ADD COLUMN IF NOT EXISTS image_url TEXT;
ALTER TABLE milestones ADD COLUMN IF NOT EXISTS image_url TEXT;
